from pathlib import Path
p=Path('/var/minis/workspace/pyvideo-plus/resources/MediaCollector.js');s=p.read_text()
# Add a network source registry alongside existing state.
s=s.replace("let timer=null,running=false,last='',lastURL=location.href,chosen=null,chosenAt=0,lastSnapshot=null;", "let timer=null,running=false,last='',lastURL=location.href,chosen=null,chosenAt=0,lastSnapshot=null;\nconst networkSources=new Map();\nconst mediaURL=v=>{if(typeof v!=='string'||!v.trim()||v.length>16384)return '';try{const u=new URL(v,document.baseURI);return /^https?:$/.test(u.protocol)?u.href:'';}catch{return '';}};\nconst classify=(url,mime='')=>{const x=(url+' '+mime).toLowerCase();if(/mpegurl|m3u8|vnd.apple.mpegurl/.test(x))return 'hls';if(/dash\\+xml|\\.mpd(?:[?#]|$)/.test(x))return 'dash';if(/video\\/|\\.(mp4|m4v|webm|mov|ts|m4s|mkv)(?:[?#]|$)/.test(x))return 'video';if(/audio\\/|\\.(m4a|mp3|aac|wav|ogg)(?:[?#]|$)/.test(x))return 'audio';return '';};\nfunction rememberNetwork(raw,mime='',headers=''){const url=mediaURL(raw),protocol=classify(url,mime);if(!url||!protocol||protocol==='audio')return;const old=networkSources.get(url)||{};networkSources.set(url,{kind:'video',url,protocol,mime:String(mime||old.mime||'').slice(0,180),headers:String(headers||old.headers||'').slice(0,1200),title:String(document.title||'影片').slice(0,180),page:location.href.slice(0,16384)});schedule();}\nfunction installNetworkProbe(){if(globalThis.__pvxNetworkProbe)return;globalThis.__pvxNetworkProbe=true;try{const oldFetch=globalThis.fetch;if(typeof oldFetch==='function')globalThis.fetch=function(input,init){try{rememberNetwork(typeof input==='string'?input:input&&input.url||'', '', init&&init.headers?JSON.stringify(init.headers):'');}catch{}const p=oldFetch.apply(this,arguments);return p.then(r=>{try{rememberNetwork(r.url,r.headers&&r.headers.get('content-type')||'',r.headers&&r.headers.get('etag')||'');}catch{}return r;});};}catch{}try{const oldOpen=XMLHttpRequest.prototype.open,oldSend=XMLHttpRequest.prototype.send;XMLHttpRequest.prototype.open=function(method,url){this.__pvxURL=url;return oldOpen.apply(this,arguments);};XMLHttpRequest.prototype.send=function(){try{rememberNetwork(this.__pvxURL||'');}catch{}this.addEventListener('readystatechange',()=>{if(this.readyState===2||this.readyState===4)try{rememberNetwork(this.__pvxURL||'',this.getResponseHeader('content-type')||'',this.getResponseHeader('etag')||'');}catch{}});return oldSend.apply(this,arguments);};}catch{}try{const oldSet=HTMLMediaElement.prototype.setAttribute;HTMLMediaElement.prototype.setAttribute=function(k,v){if(String(k).toLowerCase()==='src')rememberNetwork(v,'');return oldSet.apply(this,arguments);};}catch{}}\ninstallNetworkProbe();")
# Enrich videoRow with protocol and merge network candidates into the same video source map.
s=s.replace("videos.set(url,{kind:'video',url,sources:list,height:list[0].height,title:String(v.title||document.title||'影片').slice(0,180),poster:http(v.poster||v.getAttribute('poster'))});", "videos.set(url,{kind:'video',url,protocol:classify(url,'')||'http',sources:list,height:list[0].height,title:String(v.title||document.title||'影片').slice(0,180),poster:http(v.poster||v.getAttribute('poster'))});")
old=""" let active=null;const v=chosen;"""
new=""" for(const item of networkSources.values()){if(item.kind==='video'&&!videos.has(item.url))videos.set(item.url,{kind:'video',url:item.url,protocol:item.protocol,mime:item.mime,headers:item.headers,sources:[{url:item.url,height:0}],height:0,title:item.title,poster:''});}\n let active=null;const v=chosen;"""
assert old in s;s=s.replace(old,new,1)
p.write_text(s)
